(5647489, 820694, 109297, '<td valign="top">You are the only other person I gave a 10 to. I really love this picture. Your entry was better than mine. The only reason you are my number two pick is because I like trains so much and the other person had a train...otherwise your both equal in my book. Nice work!</td>', 'You are the only other person I gave a 10 to. I really love this picture. Your entry was better than mine. The only reason you are my number two pick is because I like trains so much and the other person had a train...otherwise your both equal in my book. Nice work!', '2009-09-15 02:27:53.000000', NULL, 1),
(5647507, 821096, 30982, '<td valign="top">You''ve done a good job with a shot of "nothing" essentially, and made it "something" - you''ve conveyed the feeling of your title very well.</td>', 'You''ve done a good job with a shot of "nothing" essentially, and made it "something" - you''ve conveyed the feeling of your title very well.', '2009-09-15 03:13:49.000000', NULL, 1),
(5647508, 820977, 30982, '<td valign="top">Love the look you see between the two gentlemen!  On top of that, the HDR brings out the detail in the animals very nicely.</td>', 'Love the look you see between the two gentlemen!  On top of that, the HDR brings out the detail in the animals very nicely.', '2009-09-15 03:14:38.000000', NULL, 1),
(5647512, 821095, 30982, '<td valign="top">All green lights - nice that they line up like that!  Warm color, very vibrant. Nice sense of energy.</td>', 'All green lights - nice that they line up like that!  Warm color, very vibrant. Nice sense of energy.', '2009-09-15 03:27:13.000000', NULL, 1),
(5647513, 820708, 30982, '<td valign="top">The HDR really brings out the work they''ve done on the structure to support it - nice!</td>', 'The HDR really brings out the work they''ve done on the structure to support it - nice!', '2009-09-15 03:27:44.000000', NULL, 1),
(5647514, 820206, 30982, '<td valign="top">Lovely the way the foreground is lit - balances well.  Very peaceful and timeless mood created here.</td>', 'Lovely the way the foreground is lit - balances well.  Very peaceful and timeless mood created here.', '2009-09-15 03:28:18.000000', NULL, 1),
(5647516, 820530, 30982, '<td valign="top">Excellent deep DOF on this and HDR really shows off the details well!  A bit of a shadow created at the cables on the handlebar (I''m sure there''s a way to fix that if you want) but a great subject for the challenge and a perfect setting to match the colors.</td>', 'Excellent deep DOF on this and HDR really shows off the details well!  A bit of a shadow created at the cables on the handlebar (I''m sure there''s a way to fix that if you want) but a great subject for the challenge and a perfect setting to match the colors.', '2009-09-15 03:29:20.000000', NULL, 1),
(5647518, 820771, 30982, '<td valign="top">I''ve always thought painted trains an excellent subject for HDR - and this is an excellent example of that!</td>', 'I''ve always thought painted trains an excellent subject for HDR - and this is an excellent example of that!', '2009-09-15 03:30:24.000000', NULL, 1),
(5647520, 820167, 30982, '<td valign="top">They almost look as though they''ve been grown there.  Nice find.</td>', 'They almost look as though they''ve been grown there.  Nice find.', '2009-09-15 03:31:09.000000', NULL, 1),
(5647521, 820838, 30982, '<td valign="top">Nifty how the overhead cover has the texture of leaves.  Nice design touch!</td>', 'Nifty how the overhead cover has the texture of leaves.  Nice design touch!', '2009-09-15 03:31:52.000000', NULL, 1),
(5647522, 820806, 30982, '<td valign="top">Nice choice of angle/perspective for this - I like how the HDR brings out the interiors of churches yet keeps the windows from blowing completely.  Nice touch with the sunlight peeking around the corner, too.</td>', 'Nice choice of angle/perspective for this - I like how the HDR brings out the interiors of churches yet keeps the windows from blowing completely.  Nice touch with the sunlight peeking around the corner, too.', '2009-09-15 03:33:15.000000', NULL, 1),
(5647523, 821095, 54645, '<td valign="top">Gotta love Philly!</td>', 'Gotta love Philly!', '2009-09-15 03:34:09.000000', NULL, 1),
(5647524, 820904, 30982, '<td valign="top">Is that a fancy word for "Teddy Bear Murderer"?  Very interesting choice of subject for the challenge, and an adorable shot!</td>', 'Is that a fancy word for "Teddy Bear Murderer"?  Very interesting choice of subject for the challenge, and an adorable shot!', '2009-09-15 03:34:17.000000', NULL, 1),
(5647525, 820410, 30982, '<td valign="top">Love the red in this!  Great perspective, good use of a square crop, Nice job with the HDR.</td>', 'Love the red in this!  Great perspective, good use of a square crop, Nice job with the HDR.', '2009-09-15 03:35:03.000000', NULL, 1),
