(5648539, 820716, 77196, '<td valign="top">The reds come out over-done on the blurry foreground boats. Nice reflections of the lights in the water.</td>', 'The reds come out over-done on the blurry foreground boats. Nice reflections of the lights in the water.', '2009-09-15 19:33:27.000000', NULL, 1),
