(5648578, 820837, 90414, '<td valign="top">Doesn''t look very HDR-ish to me, not enough detail or contrast imo. <br/>Nice comp though.</td>', 'Doesn''t look very HDR-ish to me, not enough detail or contrast imo. Nice comp though.', '2009-09-15 20:47:06.000000', NULL, 1),
