(5648583, 820465, 69668, '<td valign="top">In my top three....a HUGE 10 for you!!!</td>', 'In my top three....a HUGE 10 for you!!!', '2009-09-15 20:55:33.000000', NULL, 1),
(5648585, 821097, 69668, '<td valign="top">Very stylized image....very well done. 10</td>', 'Very stylized image....very well done. 10', '2009-09-15 20:55:56.000000', NULL, 1),
(5648595, 820779, 69668, '<td valign="top">Beautiful image....deserves higher than a 10.</td>', 'Beautiful image....deserves higher than a 10.', '2009-09-15 21:05:03.000000', NULL, 1),
(5648598, 821058, 69668, '<td valign="top">I love the fact that you chose black and white for this image.  Great image.  9</td>', 'I love the fact that you chose black and white for this image.  Great image.  9', '2009-09-15 21:05:34.000000', NULL, 1),
