(5648600, 821078, 69668, '<td valign="top">Beautiful image.  Hope to see this on the front page. 9</td>', 'Beautiful image.  Hope to see this on the front page. 9', '2009-09-15 21:06:26.000000', NULL, 1),
(5648601, 820795, 69668, '<td valign="top">Terrific capture.  9</td>', 'Terrific capture.  9', '2009-09-15 21:06:38.000000', NULL, 1),
