(5650596, 821102, 81213, '<td valign="top">I know it''s you Ken, don''t try and hide it. Another great shot, I''m a fan!!!</td>', 'I know it''s you Ken, don''t try and hide it. Another great shot, I''m a fan!!!', '2009-09-16 22:27:31.000000', NULL, 1),
