(5650598, 820206, 81213, '<td valign="top">Nice HDR, I''d like to see a little more of it in this photo though. You get a banana sticker!!!</td>', 'Nice HDR, I''d like to see a little more of it in this photo though. You get a banana sticker!!!', '2009-09-16 22:28:10.000000', NULL, 1),
(5650599, 820889, 92847, '<td valign="top">I love the colors on this shot. Nice!</td>', 'I love the colors on this shot. Nice!', '2009-09-16 22:28:38.000000', NULL, 1),
(5650600, 820305, 81213, '<td valign="top">Pictures a bit small and sky blends with the border. More contrast is needed. Composition is amazing, but to take this a step further requires some photoshop skills. Good job!</td>', 'Pictures a bit small and sky blends with the border. More contrast is needed. Composition is amazing, but to take this a step further requires some photoshop skills. Good job!', '2009-09-16 22:28:59.000000', NULL, 1),
(5650602, 820837, 81213, '<td valign="top">Looks amazing, wish i was there. i love how the tower just goes up off into the sky. Leads really well. this is done amazingly well. Only thing I would change is make the red on the Pagoda, true red and add some saturation selectively to the building. Otherwise, 6</td>', 'Looks amazing, wish i was there. i love how the tower just goes up off into the sky. Leads really well. this is done amazingly well. Only thing I would change is make the red on the Pagoda, true red and add some saturation selectively to the building. Otherwise, 6', '2009-09-16 22:30:18.000000', NULL, 1),
(5650603, 820994, 81213, '<td valign="top">Pretty, I wish you had a better cloud structure in teh background, or this photo would make my day!!!</td>', 'Pretty, I wish you had a better cloud structure in teh background, or this photo would make my day!!!', '2009-09-16 22:30:47.000000', NULL, 1),
(5650605, 820857, 81213, '<td valign="top">Loads of HDR here. Sky is over-processed. watch out for that. E for effort</td>', 'Loads of HDR here. Sky is over-processed. watch out for that. E for effort', '2009-09-16 22:31:15.000000', NULL, 1),
