INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5650608, 820990, 81213, '<td valign="top">Sick! Fantastic colors, fav and 7/10</td>', 'Sick! Fantastic colors, fav and 7/10', '2009-09-16 22:32:00.000000', NULL, 1),
(5650611, 821036, 81213, '<td valign="top">No HDR, no high vote. I would generally abide by the rule that you shouldn''t judge a photo only on how it meets the challenge. But it doesn''t look like you put any effort to make this HDR at all...</td>', 'No HDR, no high vote. I would generally abide by the rule that you shouldn''t judge a photo only on how it meets the challenge. But it doesn''t look like you put any effort to make this HDR at all...', '2009-09-16 22:33:26.000000', NULL, 1),
(5650616, 820590, 81213, '<td valign="top">Nice clouds, nice colors, no subject. Background is pretty though. I''d like to see a silhouette of maybe a kid being thrown into the air here.</td>', 'Nice clouds, nice colors, no subject. Background is pretty though. I''d like to see a silhouette of maybe a kid being thrown into the air here.', '2009-09-16 22:34:21.000000', NULL, 1),
(5650617, 821043, 81213, '<td valign="top">Beautiful clouds... Not much I can say about this though. it''s composed well, but not very interesting.</td>', 'Beautiful clouds... Not much I can say about this though. it''s composed well, but not very interesting.', '2009-09-16 22:34:56.000000', NULL, 1),
(5650618, 820732, 81213, '<td valign="top">Whiterook?</td>', 'Whiterook?', '2009-09-16 22:35:07.000000', NULL, 1),
