(5650632, 820686, 108687, '<td valign="top">Other than the bright street light this is a really nice shot.</td>', 'Other than the bright street light this is a really nice shot.', '2009-09-16 22:42:35.000000', NULL, 1),
(5650633, 820592, 81213, '<td valign="top">Don;t like the flash at all in this. I hate flash, i''d give this a higher rating for competition, but flash kills it. Sorry, hope others aren''t as bothered by it as I am.</td>', 'Don;t like the flash at all in this. I hate flash, i''d give this a higher rating for competition, but flash kills it. Sorry, hope others aren''t as bothered by it as I am.', '2009-09-16 22:42:51.000000', NULL, 1),
(5650634, 820734, 81213, '<td valign="top">That''s a killer shot man. Great job! Nice colors and HDR is done well. 6/10</td>', 'That''s a killer shot man. Great job! Nice colors and HDR is done well. 6/10', '2009-09-16 22:43:26.000000', NULL, 1),
(5650635, 820878, 81213, '<td valign="top">Too dark, nice colors, just brighten the background up a bit. 6/10</td>', 'Too dark, nice colors, just brighten the background up a bit. 6/10', '2009-09-16 22:44:00.000000', NULL, 1),
(5650637, 820672, 81213, '<td valign="top">AMAZING contrast here. Your subject is a little close to the building on the left and HDR is a bit overdone. But whatever floats your boat... 6</td>', 'AMAZING contrast here. Your subject is a little close to the building on the left and HDR is a bit overdone. But whatever floats your boat... 6', '2009-09-16 22:44:50.000000', NULL, 1),
(5650640, 821097, 83313, '<td valign="top">A good application of a style I''ve seen used in sports pics before. Very dramatic looking.</td>', 'A good application of a style I''ve seen used in sports pics before. Very dramatic looking.', '2009-09-16 22:45:04.000000', NULL, 1),
(5650644, 821060, 81213, '<td valign="top">Greta shadows, colors, whole picture looks like a drawing, especially the hills behind the clouds. Sky is efing amazing, and lighting here is unbelievable. Fav and 7/10</td>', 'Greta shadows, colors, whole picture looks like a drawing, especially the hills behind the clouds. Sky is efing amazing, and lighting here is unbelievable. Fav and 7/10', '2009-09-16 22:45:53.000000', NULL, 1),
(5650645, 821049, 83313, '<td valign="top">Good enough, but it is not coming off to me any different than many similar shots I''ve seen here. Maybe my senses have been dulled...</td>', 'Good enough, but it is not coming off to me any different than many similar shots I''ve seen here. Maybe my senses have been dulled...', '2009-09-16 22:46:12.000000', NULL, 1),
(5650646, 821093, 83313, '<td valign="top">Heavily over the top here, but I think it does the subject well.</td>', 'Heavily over the top here, but I think it does the subject well.', '2009-09-16 22:47:16.000000', NULL, 1),
(5650647, 820900, 81213, '<td valign="top">The tilt bothers me, but water is pretty and colors are fantastic. Sky is a little too separated from the dock because it is so sepia and the dock has so much saturation. Nice try, but technical errors take it down to a five for me. Also, the dock doesn''t really seem like a dock. I would have liked it more had that stone been an old wood dock falling to pieces. good try! You''ve got a great eye.</td>', 'The tilt bothers me, but water is pretty and colors are fantastic. Sky is a little too separated from the dock because it is so sepia and the dock has so much saturation. Nice try, but technical errors take it down to a five for me. Also, the dock doesn''t really seem like a dock. I would have liked it more had that stone been an old wood dock falling to pieces. good try! You''ve got a great eye.', '2009-09-16 22:47:43.000000', NULL, 1),
(5650649, 820530, 83313, '<td valign="top">Very smooth an detailed. This sort of treatment is what I think of when I hear the term HDR.</td>', 'Very smooth an detailed. This sort of treatment is what I think of when I hear the term HDR.', '2009-09-16 22:48:08.000000', NULL, 1),
(5650651, 820964, 81213, '<td valign="top">God, what a DUNCE nice colors and HDR anyway. 6/10</td>', 'God, what a DUNCE nice colors and HDR anyway. 6/10', '2009-09-16 22:48:38.000000', NULL, 1),
(5650652, 821102, 83313, '<td valign="top">Losing track of how many times I''ve seen this lighthouse, and I''ve never been there! Hey, a good subject is a good subject, right?</td>', 'Losing track of how many times I''ve seen this lighthouse, and I''ve never been there! Hey, a good subject is a good subject, right?', '2009-09-16 22:49:22.000000', NULL, 1),
(5650655, 821094, 81213, '<td valign="top">Very pretty, great HDR and mood set. A little over saturated for my taste. Would love to see this B&amp;W or a bit more de-sat. Love the feeling it makes. Cracked window is cool, looks like spider web. Good job, hope you get the score you were looking for!</td>', 'Very pretty, great HDR and mood set. A little over saturated for my taste. Would love to see this B&W or a bit more de-sat. Love the feeling it makes. Cracked window is cool, looks like spider web. Good job, hope you get the score you were looking for!', '2009-09-16 22:50:01.000000', NULL, 1),
(5650657, 820896, 81213, '<td valign="top">Cute little photo, never seen anything quite like it. 5 for competition and +1 for originality. 6/10</td>', 'Cute little photo, never seen anything quite like it. 5 for competition and +1 for originality. 6/10', '2009-09-16 22:50:40.000000', NULL, 1),
(5650658, 820806, 81213, '<td valign="top">Interesting, don''t really know what to say. Great job! 6</td>', 'Interesting, don''t really know what to say. Great job! 6', '2009-09-16 22:51:09.000000', NULL, 1),
(5650660, 820962, 83313, '<td valign="top">All this is missing is an exotic beauty rinsing her hair under the waterfall. (Then it would be a shampoo commercial!)</td>', 'All this is missing is an exotic beauty rinsing her hair under the waterfall. (Then it would be a shampoo commercial!)', '2009-09-16 22:51:16.000000', NULL, 1),
(5650662, 820411, 81213, '<td valign="top">Wow, that''s a very... powerful image. Gave me a seizure just scrolling down to leave the comment.</td>', 'Wow, that''s a very... powerful image. Gave me a seizure just scrolling down to leave the comment.', '2009-09-16 22:51:54.000000', NULL, 1),
