(5650692, 820692, 81213, '<td valign="top">Too much HDR, but I love how the roller coaster is all the same color and pokes out of the trees and leads you back into the image. 6/10</td>', 'Too much HDR, but I love how the roller coaster is all the same color and pokes out of the trees and leads you back into the image. 6/10', '2009-09-16 23:02:40.000000', NULL, 1),
(5650693, 821058, 81213, '<td valign="top">Beautiful... Fav and 7/10 Best B&amp;W I''ve seen i a while</td>', 'Beautiful... Fav and 7/10 Best B&W I''ve seen i a while', '2009-09-16 23:03:11.000000', NULL, 1),
