(5650972, 820959, 64446, '<td valign="top">One of the rare B&amp;W HDR. Nicely done. I wonder why the back is a bit cut away...</td>', 'One of the rare B&W HDR. Nicely done. I wonder why the back is a bit cut away...', '2009-09-17 01:06:25.000000', NULL, 1),
(5650973, 821044, 64446, '<td valign="top">Nicely complicated and wonderful to watch.</td>', 'Nicely complicated and wonderful to watch.', '2009-09-17 01:06:54.000000', NULL, 1),
