(5650977, 820141, 64446, '<td valign="top">Wow, amazing perspectove and leading lines. At a first glance it looks like a cathedral.</td>', 'Wow, amazing perspectove and leading lines. At a first glance it looks like a cathedral.', '2009-09-17 01:08:51.000000', NULL, 1),
(5650978, 820465, 64446, '<td valign="top">Lol. Very funny and well composed!</td>', 'Lol. Very funny and well composed!', '2009-09-17 01:08:55.000000', NULL, 1),
(5650979, 820483, 64446, '<td valign="top">Love the vivid colours. Nicely composed.</td>', 'Love the vivid colours. Nicely composed.', '2009-09-17 01:09:29.000000', NULL, 1),
(5650981, 820715, 99981, '<td valign="top">This makes me remember of a beatles videoclip. Nice shot!</td>', 'This makes me remember of a beatles videoclip. Nice shot!', '2009-09-17 01:09:43.000000', NULL, 1),
(5650982, 820996, 64446, '<td valign="top">Unique monument and point of view. I like the contrast of the B&amp;W of the ceramic and clouds with the strong saturated green.</td>', 'Unique monument and point of view. I like the contrast of the B&W of the ceramic and clouds with the strong saturated green.', '2009-09-17 01:11:08.000000', NULL, 1),
(5650983, 821071, 64446, '<td valign="top">I like its simplicity and the story...</td>', 'I like its simplicity and the story...', '2009-09-17 01:11:12.000000', NULL, 1),
(5650984, 820795, 64446, '<td valign="top">This is a terrific capture! Amazing the wind at the wings...</td>', 'This is a terrific capture! Amazing the wind at the wings...', '2009-09-17 01:11:16.000000', NULL, 1),
(5650985, 820171, 64446, '<td valign="top">Here''s a non-traditional HDR, but it''s nice how you got the details from the water at the foreground as well as on the mountains.  Most amazing is how the mountain tops is "floating" above all scene. Well done!</td>', 'Here''s a non-traditional HDR, but it''s nice how you got the details from the water at the foreground as well as on the mountains.  Most amazing is how the mountain tops is "floating" above all scene. Well done!', '2009-09-17 01:11:19.000000', NULL, 1);
