(5650986, 820779, 64446, '<td valign="top">Beautiful peaceful image. Very very nice...</td>', 'Beautiful peaceful image. Very very nice...', '2009-09-17 01:11:59.000000', NULL, 1),
(5650989, 820729, 99981, '<td valign="top">The exposure is really beautiful and those colors too. The sky is just a liiittle noisy in my opinion. Great shot!</td>', 'The exposure is really beautiful and those colors too. The sky is just a liiittle noisy in my opinion. Great shot!', '2009-09-17 01:14:20.000000', NULL, 1),
(5650990, 820559, 64446, '<td valign="top">A little bit oversaturated but I like the rainbow colours and the silhouettes too. I wonder why the water horizon line is not leveled...</td>', 'A little bit oversaturated but I like the rainbow colours and the silhouettes too. I wonder why the water horizon line is not leveled...', '2009-09-17 01:14:24.000000', NULL, 1),
(5650993, 820717, 99981, '<td valign="top">The HDR, pp, colors and DOF are really great and the shot is great in general. But that yellow glow at the right/middle is kind of distracting.</td>', 'The HDR, pp, colors and DOF are really great and the shot is great in general. But that yellow glow at the right/middle is kind of distracting.', '2009-09-17 01:15:32.000000', NULL, 1),
(5650996, 819840, 64446, '<td valign="top">Terrific powerful image! Love the vibrant blue and the tower reflection is a nice serenpity touch...</td>', 'Terrific powerful image! Love the vibrant blue and the tower reflection is a nice serenpity touch...', '2009-09-17 01:16:31.000000', NULL, 1),
(5650997, 820729, 64446, '<td valign="top">Lovely. Amazing stillness of the reflection.</td>', 'Lovely. Amazing stillness of the reflection.', '2009-09-17 01:16:36.000000', NULL, 1),
(5650998, 820575, 99981, '<td valign="top">The DOF is really pleasing on this shot. Good job with the colors at the foreground too.</td>', 'The DOF is really pleasing on this shot. Good job with the colors at the foreground too.', '2009-09-17 01:16:53.000000', NULL, 1),
(5651003, 820634, 64446, '<td valign="top">That''s very dramatic. Along with the skies, the ground with its puddles also contributes for a intense impact to the viewer. Very good job!</td>', 'That''s very dramatic. Along with the skies, the ground with its puddles also contributes for a intense impact to the viewer. Very good job!', '2009-09-17 01:20:44.000000', NULL, 1),
(5651005, 821033, 99981, '<td valign="top">Aw, great! I''ll wait to see which aperture and exposure did you use, this is really nice!</td>', 'Aw, great! I''ll wait to see which aperture and exposure did you use, this is really nice!', '2009-09-17 01:21:00.000000', NULL, 1),
(5651007, 820858, 64446, '<td valign="top">Very nice composition (no pun intended...). Intriguing that no people is shown (even the conductor).</td>', 'Very nice composition (no pun intended...). Intriguing that no people is shown (even the conductor).', '2009-09-17 01:22:20.000000', NULL, 1),
(5651010, 820923, 99981, '<td valign="top">My favorite so far. Stunning image. 10!</td>', 'My favorite so far. Stunning image. 10!', '2009-09-17 01:23:05.000000', NULL, 1),
(5651011, 820858, 99981, '<td valign="top">One my favorites so far. The details and the DOF are great, so as the colors, composition and use of light. This shot has a misterious mood, it''s really great.</td>', 'One my favorites so far. The details and the DOF are great, so as the colors, composition and use of light. This shot has a misterious mood, it''s really great.', '2009-09-17 01:23:30.000000', NULL, 1),
