(5651013, 820889, 99981, '<td valign="top">Did you told everybody to stay at home? Woa! Amazing shot!</td>', 'Did you told everybody to stay at home? Woa! Amazing shot!', '2009-09-17 01:24:54.000000', NULL, 1),
(5651014, 820914, 99981, '<td valign="top">This is one of my favorites in this challenge. Hope you can show us the 3 captures or the single original.</td>', 'This is one of my favorites in this challenge. Hope you can show us the 3 captures or the single original.', '2009-09-17 01:25:19.000000', NULL, 1),
