(5654629, 820838, 64446, '<td valign="top">Nice composition and lighting on this (almost) simetric image.</td>', 'Nice composition and lighting on this (almost) simetric image.', '2009-09-20 17:43:03.000000', NULL, 1),
(5654631, 820036, 64446, '<td valign="top">Nice, it seems slightly tilted.</td>', 'Nice, it seems slightly tilted.', '2009-09-20 17:44:11.000000', NULL, 1),
(5654635, 820994, 64446, '<td valign="top">Nice compositon. Like the nuances &amp; textures of the water &amp; sky, and details of the rocks &amp; poles in the foreground.</td>', 'Nice compositon. Like the nuances & textures of the water & sky, and details of the rocks & poles in the foreground.', '2009-09-20 17:47:21.000000', NULL, 1),
(5654636, 820978, 64446, '<td valign="top">Would be more interesting if there were somethng on the foreground to draw the attention to.</td>', 'Would be more interesting if there were somethng on the foreground to draw the attention to.', '2009-09-20 17:48:07.000000', NULL, 1),
(5654637, 820857, 64446, '<td valign="top">Power/telephone lines spoil it. Nice pp.</td>', 'Power/telephone lines spoil it. Nice pp.', '2009-09-20 17:49:32.000000', NULL, 1),
(5654638, 820410, 64446, '<td valign="top">This is in fact interesting. As if you had part of the wheel cloned out. I think the large border distracts.</td>', 'This is in fact interesting. As if you had part of the wheel cloned out. I think the large border distracts.', '2009-09-20 17:52:28.000000', NULL, 1),
(5654640, 820631, 64446, '<td valign="top">Great reflections.</td>', 'Great reflections.', '2009-09-20 17:52:47.000000', NULL, 1),
(5654641, 820983, 64446, '<td valign="top">What a finding. Love the color coordination: green, blue &amp; rust-red. Better if there was no sky showing up.</td>', 'What a finding. Love the color coordination: green, blue & rust-red. Better if there was no sky showing up.', '2009-09-20 17:54:19.000000', NULL, 1),
(5654642, 821093, 64446, '<td valign="top">Nice colours. Could have cloned that telephone line.</td>', 'Nice colours. Could have cloned that telephone line.', '2009-09-20 17:55:06.000000', NULL, 1),
(5654644, 821060, 64446, '<td valign="top">Nice view. Love the mountain range at the back.</td>', 'Nice view. Love the mountain range at the back.', '2009-09-20 17:56:13.000000', NULL, 1),
(5654648, 820368, 64446, '<td valign="top">Too bad many won''t get the title. Love fisheye effect and the vibrant and warm colors. Nice composition, although the limo steals a bit the attention.</td>', 'Too bad many won''t get the title. Love fisheye effect and the vibrant and warm colors. Nice composition, although the limo steals a bit the attention.', '2009-09-20 18:01:24.000000', NULL, 1),
(5654671, 821006, 30982, '<td valign="top">Love the composition of this, and the HDR adds to the rather ominous feeling the composition engenders.</td>', 'Love the composition of this, and the HDR adds to the rather ominous feeling the composition engenders.', '2009-09-20 18:40:39.000000', NULL, 1),
(5654681, 821005, 103142, '<td valign="top">ok, you probably have gotten "over-processed" comments, but I''m liking the overprocessed look here! Slight thing, it looks tilted. I think I would have straightened on the bottom, back part of the house, instead of the roofline... ?</td>', 'ok, you probably have gotten "over-processed" comments, but I''m liking the overprocessed look here! Slight thing, it looks tilted. I think I would have straightened on the bottom, back part of the house, instead of the roofline... ?', '2009-09-20 19:12:19.000000', NULL, 1),
(5654689, 820919, 106349, '<td valign="top">What a cool place! I consider this a great use of HDR. Nicely done!</td>', 'What a cool place! I consider this a great use of HDR. Nicely done!', '2009-09-20 19:25:13.000000', NULL, 1),
(5654690, 821025, 106349, '<td valign="top">It''s clearly overprocessed but I really like the way it looks... except for the noise in the sky where it''s dark blue. Should be easy to fix, though.</td>', 'It''s clearly overprocessed but I really like the way it looks... except for the noise in the sky where it''s dark blue. Should be easy to fix, though.', '2009-09-20 19:26:28.000000', NULL, 1),
(5654691, 820559, 106349, '<td valign="top">What great colors! The subject seems a little dark, though, as well as the front where the fence is. I guess the fence is ok like that but I''d like to see a little more spotlight on the windmill (it''s so cool looking, though!).</td>', 'What great colors! The subject seems a little dark, though, as well as the front where the fence is. I guess the fence is ok like that but I''d like to see a little more spotlight on the windmill (it''s so cool looking, though!).', '2009-09-20 19:27:29.000000', NULL, 1),
(5654692, 820465, 106349, '<td valign="top">Looks like a ribbon winner to me!</td>', 'Looks like a ribbon winner to me!', '2009-09-20 19:27:52.000000', NULL, 1),
(5654693, 820552, 106349, '<td valign="top">I really like the shot but think the vehicles kind of take away from it.</td>', 'I really like the shot but think the vehicles kind of take away from it.', '2009-09-20 19:28:26.000000', NULL, 1),
(5654694, 821099, 106349, '<td valign="top">I''ve rarely seen so many shades of gray in one picture. You really did a good job. Has a very holiday look to it.</td>', 'I''ve rarely seen so many shades of gray in one picture. You really did a good job. Has a very holiday look to it.', '2009-09-20 19:29:20.000000', NULL, 1),
(5654696, 820734, 106349, '<td valign="top">You captured a great range of colors in the city.</td>', 'You captured a great range of colors in the city.', '2009-09-20 19:29:55.000000', NULL, 1),
(5654697, 820058, 106349, '<td valign="top">I really like everything about this except the noise in the blue part of the sky.</td>', 'I really like everything about this except the noise in the blue part of the sky.', '2009-09-20 19:32:19.000000', NULL, 1),
(5654699, 820672, 106349, '<td valign="top">This looks great! Hope it''s doing well. (didn''t vote)</td>', 'This looks great! Hope it''s doing well. (didn''t vote)', '2009-09-20 19:33:01.000000', NULL, 1),
