(5655204, 820988, 83313, '<td valign="top">Well into the top half. a strong showing. Sk8er boy did well for you. You need to make sure he gets a large print of this.</td>', 'Well into the top half. a strong showing. Sk8er boy did well for you. You need to make sure he gets a large print of this.', '2009-09-21 01:36:57.000000', NULL, 0),
(5655206, 820941, 67697, '<td valign="top">All the lights on the building is wonderful!  Such a pretty sky too.  Beautiful combo.</td>', 'All the lights on the building is wonderful!  Such a pretty sky too.  Beautiful combo.', '2009-09-21 01:38:00.000000', NULL, 0),
(5655207, 820465, 61961, '<td valign="top">Big congrats, Lydia!  So glad this did so well for you and made the top ten.</td>', 'Big congrats, Lydia!  So glad this did so well for you and made the top ten.', '2009-09-21 01:38:03.000000', NULL, 0),
(5655208, 821094, 74911, '<td valign="top">Great score for a first entry. Congrats on the top 20 finish!</td>', 'Great score for a first entry. Congrats on the top 20 finish!', '2009-09-21 01:38:09.000000', NULL, 0),
