(5655217, 820779, 54446, '<td valign="top">Super beautiful image which absolutely belongs near the top of this challenge. Congratulations.</td>', 'Super beautiful image which absolutely belongs near the top of this challenge. Congratulations.', '2009-09-21 01:43:16.000000', NULL, 0),
(5655219, 820343, 61961, '<td valign="top">Should win a <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=50695" rel="nofollow" target="_blank">posthumous</a> award!  So strange and eerily beautiful, though not sure how much HDR was involved.  I read your description; I''m not sure I understood everything you did, but be careful you stay within editing bounds.   Cheers,</td>', 'Should win a  posthumous award!  So strange and eerily beautiful, though not sure how much HDR was involved.  I read your description; I''m not sure I understood everything you did, but be careful you stay within editing bounds.   Cheers,', '2009-09-21 01:43:30.000000', NULL, 0),
