(5655222, 821058, 54446, '<td valign="top">Dramatic image, which I''ve studied a lot, due to its dramatic impact on the viewer.  Congrats on your top 10 finish.</td>', 'Dramatic image, which I''ve studied a lot, due to its dramatic impact on the viewer.  Congrats on your top 10 finish.', '2009-09-21 01:45:16.000000', NULL, 0),
(5655223, 820986, 83313, '<td valign="top">Nice job on this, I see it made your profile page. That always makes for a good one. It got an 8 from me. I also see you appealed to the very hard to please (at least for this challenge) <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/31.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/31.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/31.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=97166" rel="nofollow" target="_blank">K10Dguy</a>.</td>', 'Nice job on this, I see it made your profile page. That always makes for a good one. It got an 8 from me. I also see you appealed to the very hard to please (at least for this challenge)  K10Dguy.', '2009-09-21 01:45:21.000000', NULL, 0),
(5655225, 820465, 54446, '<td valign="top">Wonderful image.  Congrats on your top 10 finish!</td>', 'Wonderful image.  Congrats on your top 10 finish!', '2009-09-21 01:46:11.000000', NULL, 0),
(5655227, 821005, 54446, '<td valign="top">Congrats on your top 10 finish!</td>', 'Congrats on your top 10 finish!', '2009-09-21 01:46:44.000000', NULL, 0),
(5655228, 820906, 61961, '<td valign="top">I think this was underrated by most voters.  I like the limited palette, the high key quality and the clarity.</td>', 'I think this was underrated by most voters.  I like the limited palette, the high key quality and the clarity.', '2009-09-21 01:47:11.000000', NULL, 0),
