(5655230, 820410, 30982, '<td valign="top">Hey, congrats on a top ten, and an outstanding score!  And love the "thankfully, it was still under warranty".... :-)</td>', 'Hey, congrats on a top ten, and an outstanding score!  And love the "thankfully, it was still under warranty".... :-)', '2009-09-21 01:47:36.000000', NULL, 0),
(5655231, 820959, 54446, '<td valign="top">Dramatic b&amp;w image.  Well processed!  Congrats on your top 10 finish!</td>', 'Dramatic b&w image.  Well processed!  Congrats on your top 10 finish!', '2009-09-21 01:47:39.000000', NULL, 0),
(5655233, 820410, 54446, '<td valign="top">Unique and interesting image with lots of technical excellence.  Congrats on your top 10 finish!</td>', 'Unique and interesting image with lots of technical excellence.  Congrats on your top 10 finish!', '2009-09-21 01:48:28.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5655234, 821006, 30982, '<td valign="top">That is HDR, you know.  The "real" way - by hand.  So it DOES count, you silly man.  And indeed was one of those I visited repeatedly.  Nifty shot.  LOVE that you changed apertures and ISO, and not shutter.  Very innovative!  I shall have to try that.  And (insert deity of choice here) bless the 10-22, for it is good.</td>', 'That is HDR, you know.  The "real" way - by hand.  So it DOES count, you silly man.  And indeed was one of those I visited repeatedly.  Nifty shot.  LOVE that you changed apertures and ISO, and not shutter.  Very innovative!  I shall have to try that.  And (insert deity of choice here) bless the 10-22, for it is good.', '2009-09-21 01:50:45.000000', NULL, 0),
(5655236, 821036, 83313, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by ColemanGariety:</b></div><hr/><i> But it doesn''t look like you put any effort to make this HDR at all... </i></td></tr></table> <br/>I rarely feel the need to counter someone in comments like this, but there is clearly effort behind this. It may not have come off with as much visual impact as other entries in this challenge, but without the use of HDR this would have been a dark tunnel, and it certainly shows the use of the technique.</td>', 'Originally posted by ColemanGariety: But it doesn''t look like you put any effort to make this HDR at all...  I rarely feel the need to counter someone in comments like this, but there is clearly effort behind this. It may not have come off with as much visual impact as other entries in this challenge, but without the use of HDR this would have been a dark tunnel, and it certainly shows the use of the technique.', '2009-09-21 01:53:41.000000', NULL, 0),
(5655237, 821012, 83313, '<td valign="top">Another one that I felt was way underrated. Probably because you kept it real looking. That theory is also supported by the fact that K-man valued it at a 7. It got an 8 from me.</td>', 'Another one that I felt was way underrated. Probably because you kept it real looking. That theory is also supported by the fact that K-man valued it at a 7. It got an 8 from me.', '2009-09-21 01:56:12.000000', NULL, 0),
(5655239, 820735, 83313, '<td valign="top">This was a strange challenge. I am still finding some of my own highest rated shots well into the mid 5''s. Got a 9 and a fave from me.</td>', 'This was a strange challenge. I am still finding some of my own highest rated shots well into the mid 5''s. Got a 9 and a fave from me.', '2009-09-21 01:57:27.000000', NULL, 0),
(5655241, 820838, 62357, '<td valign="top">Seriously disappointed that this did not score much higher.  It''s a really excellent one.</td>', 'Seriously disappointed that this did not score much higher.  It''s a really excellent one.', '2009-09-21 01:58:16.000000', NULL, 0),
