(5655760, 820889, 49109, '<td valign="top">Seriously underrated, my top pick.</td>', 'Seriously underrated, my top pick.', '2009-09-21 12:37:57.000000', NULL, 0),
(5655762, 821096, 23484, '<td valign="top">This is very nice. I''ve noticed that in 99.9% of these HDR shots, they all seem to have an edgy feel that seems to jump right out and knock you over. Even in the images where a peaceful lake was photographed, it still has that knockout punch.  You have somehow found a way to display the serene in a process that just doesn''t seem conducive to that. This is just my opinion.  Nice job.</td>', 'This is very nice. I''ve noticed that in 99.9% of these HDR shots, they all seem to have an edgy feel that seems to jump right out and knock you over. Even in the images where a peaceful lake was photographed, it still has that knockout punch.  You have somehow found a way to display the serene in a process that just doesn''t seem conducive to that. This is just my opinion.  Nice job.', '2009-09-21 12:38:50.000000', NULL, 0),
(5655765, 821040, 23484, '<td valign="top">Outstanding job.</td>', 'Outstanding job.', '2009-09-21 12:40:40.000000', NULL, 0),
