(5656976, 820779, 67145, '<td valign="top">congratulations alfredo on such a stunning shot and your fourth place .. :)</td>', 'congratulations alfredo on such a stunning shot and your fourth place .. :)', '2009-09-22 07:10:48.000000', NULL, 0),
(5657037, 821025, 103916, '<td valign="top">I know it seems a bit over done and overly bright and colorful.  I suppose living in the desert makes you miss trees, rain/water, greenery, flowers, and most of all color!!!  Las Vegas neon lights sure are pretty but, there is nothing like color in nature.  I shot this picture at Tulley Springs, when I saw the reflection I got all gitty and decided that I would make it very colorful.  I suppose many disagreed with the look but, I suppose in my mind, that is exactly the way the colors should be.  Thanks for all the comments!!! =)</td>', 'I know it seems a bit over done and overly bright and colorful.  I suppose living in the desert makes you miss trees, rain/water, greenery, flowers, and most of all color!!!  Las Vegas neon lights sure are pretty but, there is nothing like color in nature.  I shot this picture at Tulley Springs, when I saw the reflection I got all gitty and decided that I would make it very colorful.  I suppose many disagreed with the look but, I suppose in my mind, that is exactly the way the colors should be.  Thanks for all the comments!!! =)', '2009-09-22 09:28:23.000000', NULL, 0),
(5657110, 821005, 8759, '<td valign="top">Congrats for top 10...</td>', 'Congrats for top 10...', '2009-09-22 10:17:55.000000', NULL, 0),
