(5657795, 821088, 108384, '<td valign="top">My favorite shot of the challenge.  How did this place so low?</td>', 'My favorite shot of the challenge.  How did this place so low?', '2009-09-22 19:41:43.000000', NULL, 0),
(5657981, 821094, 99256, '<td valign="top">Great shot, congrats on such a high finish on your first entry.  I agree with the comment below it does look a lot like <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=63398" rel="nofollow" target="_blank">nikonjeb</a>.  I think you might like some of his work.  <br/> <br/>Back to your shot.  I like it.  It''s a little over the top but thats ok, and thats kinda the idea with this challenge.  I would love to see the individual shots you combined.  I also agree that black and white would probably look good too.  Good job.</td>', 'Great shot, congrats on such a high finish on your first entry.  I agree with the comment below it does look a lot like  nikonjeb.  I think you might like some of his work.   Back to your shot.  I like it.  It''s a little over the top but thats ok, and thats kinda the idea with this challenge.  I would love to see the individual shots you combined.  I also agree that black and white would probably look good too.  Good job.', '2009-09-22 21:04:43.000000', NULL, 0),
(5658012, 821078, 66635, '<td valign="top">I grew up in Northern Virginia and have seen many pictures of Great Falls.  I think I even have one in my portfolio.  But this is by far the best I''ve ever seen.  Congratulations on a job well done and a well-earned ribbon.</td>', 'I grew up in Northern Virginia and have seen many pictures of Great Falls.  I think I even have one in my portfolio.  But this is by far the best I''ve ever seen.  Congratulations on a job well done and a well-earned ribbon.', '2009-09-22 21:14:39.000000', NULL, 0),
(5658081, 819840, 30456, '<td valign="top">Great story to accompany a great photo.  Congratulations on the ribbon.</td>', 'Great story to accompany a great photo.  Congratulations on the ribbon.', '2009-09-22 22:12:23.000000', NULL, 0),
(5658190, 819840, 91360, '<td valign="top">wonderful story and picture, I would have try taking this at lower ISO (100)with a tripod at shutter speed of approx 1\6 sec.</td>', 'wonderful story and picture, I would have try taking this at lower ISO (100)with a tripod at shutter speed of approx 1\6 sec.', '2009-09-22 23:59:46.000000', NULL, 0),
(5658197, 820410, 67697, '<td valign="top">I thought this was a great HDR shot - the details on the wheel are fabulous!  But I really loved the sky - it was my favorite part.  Congrats on 10th place and your new PB!</td>', 'I thought this was a great HDR shot - the details on the wheel are fabulous!  But I really loved the sky - it was my favorite part.  Congrats on 10th place and your new PB!', '2009-09-23 00:04:35.000000', NULL, 0),
(5658666, 820923, 23430, '<td valign="top">This is a very striking shot. I think you''ve really improved it to with the HDR too. Congrats on the awesome score, well deserved.</td>', 'This is a very striking shot. I think you''ve really improved it to with the HDR too. Congrats on the awesome score, well deserved.', '2009-09-23 05:00:22.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5658672, 819840, 23430, '<td valign="top">Really nice shot. The composition is great. Congrats on the Red</td>', 'Really nice shot. The composition is great. Congrats on the Red', '2009-09-23 05:01:59.000000', NULL, 0),
(5658680, 821005, 69886, '<td valign="top">The HDR may be over done, but I think it looks great. I wish the world looked like that.... <br/> <br/>I love it, and would hang it on my wall if it was a print.</td>', 'The HDR may be over done, but I think it looks great. I wish the world looked like that....  I love it, and would hang it on my wall if it was a print.', '2009-09-23 05:10:42.000000', NULL, 0),
(5658774, 821071, 30982, '<td valign="top">Has a nice mellow afternoon feel to it.  Score is very good, so folks liked it and thought the HDR added to the shot.  Key plusses - simple, well balanced, well lit, and the HDR did help balance out the difference in lighting from inside to out.  The top window panes have a distintive "burned" grayness to them and there is a bit of haloing around the tub - signs of HDR.  Oddly that probably was a good thing in this challenge.  :-)</td>', 'Has a nice mellow afternoon feel to it.  Score is very good, so folks liked it and thought the HDR added to the shot.  Key plusses - simple, well balanced, well lit, and the HDR did help balance out the difference in lighting from inside to out.  The top window panes have a distintive "burned" grayness to them and there is a bit of haloing around the tub - signs of HDR.  Oddly that probably was a good thing in this challenge.  :-)', '2009-09-23 07:38:11.000000', NULL, 0),
(5658843, 820858, 772, '<td valign="top">Greetings from the Critique Club...<br/> <br/>HDR is a subject that I''m not overly impressed with in the long run.  MOST (but not all) of the HDR images I have seen simply don''t look natural to me and they have a look of being over processed.  I believe that the simple nature of these tools convince a lot of photographers that there is some overpowering need to make the photo have a processed rather than a natural appearance.  My personal interests in photography are for a more natural appearance.  I personally tend to not like a photograph when its main theme has become a processing technique rather than the normal elements of subject and composition.  <br/> <br/>That being said, your photograph scored rather well in this challenge with a score of 6.56.  As I look at your image (and set aside the elements of HDR), I find myself looking around the scene trying to determine what part of it you found to be the most intriguing and what it is you wanted me, as the viewer, to see in this scene.  The rear of the train seems to be the focus point of the image, and it is falling dead center in the frame.  I''m also struggling with the lighting, and it may be that a selective desaturation was used in this image, but I''m not sure.  The yellow cast behind the train just looks and feels strange to me when there is no other light with that tone in the scene.  <br/> <br/>I really do feel unqualified to offer reasonable critique on this image since I simply do not like the whole HDR concept for the most part...</td>', 'Greetings from the Critique Club... HDR is a subject that I''m not overly impressed with in the long run.  MOST (but not all) of the HDR images I have seen simply don''t look natural to me and they have a look of being over processed.  I believe that the simple nature of these tools convince a lot of photographers that there is some overpowering need to make the photo have a processed rather than a natural appearance.  My personal interests in photography are for a more natural appearance.  I personally tend to not like a photograph when its main theme has become a processing technique rather than the normal elements of subject and composition.   That being said, your photograph scored rather well in this challenge with a score of 6.56.  As I look at your image (and set aside the elements of HDR), I find myself looking around the scene trying to determine what part of it you found to be the most intriguing and what it is you wanted me, as the viewer, to see in this scene.  The rear of the train seems to be the focus point of the image, and it is falling dead center in the frame.  I''m also struggling with the lighting, and it may be that a selective desaturation was used in this image, but I''m not sure.  The yellow cast behind the train just looks and feels strange to me when there is no other light with that tone in the scene.   I really do feel unqualified to offer reasonable critique on this image since I simply do not like the whole HDR concept for the most part...', '2009-09-23 09:08:22.000000', NULL, 0),
(5658975, 820987, 51269, '<td valign="top">Spectacular image , Peter !</td>', 'Spectacular image , Peter !', '2009-09-23 10:19:01.000000', NULL, 0),
