(5659384, 820686, 90231, '<td valign="top">I immediately recognized this as Mead Library in Sheboygan. I am from Oostburg, and it is one of my favorite places in Sheboygan. Thanks for the great photo!</td>', 'I immediately recognized this as Mead Library in Sheboygan. I am from Oostburg, and it is one of my favorite places in Sheboygan. Thanks for the great photo!', '2009-09-23 14:45:15.000000', NULL, 0),
(5659638, 820529, 42013, '<td valign="top">highly underrated. Good work!</td>', 'highly underrated. Good work!', '2009-09-23 17:10:11.000000', NULL, 0),
(5659743, 821044, 41976, '<td valign="top">As someone who does a lot of HDR, I think this is one of the best I''ve seen.  As as for not being "a very engaging photo", I really like going back to view it.  Nice work.</td>', 'As someone who does a lot of HDR, I think this is one of the best I''ve seen.  As as for not being "a very engaging photo", I really like going back to view it.  Nice work.', '2009-09-23 17:58:11.000000', NULL, 0),
